insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-9a', 'world-9', 'dead-air', '9A - Dead Air', 'SkyPort maintenance devices are connecting to an access point that doesn''t exist in inventory.', 1);
insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-9a-1', 'campaign-9a', 'foundations', 'Foundations', '802.11, WPA generations and nearby radio technologies, learned to broaden the threat model beyond cables.', 1),
  ('operation-9a-2', 'campaign-9a', 'investigation', 'Investigation', 'Locate the rogue access point and redesign wireless controls.', 2);
insert into public.missions (
insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w9-01', 1, 'zayn', 'The beacon came in over SkyPort''s wireless maintenance network. There''s an access point in the traffic logs that doesn''t exist in inventory.'),
  ('mission-w9-01', 2, 'zayn', 'Wireless changes the threat model completely. There''s no cable to trace, no port to unplug. An attacker just has to be close enough to the air itself.'),
  ('mission-w9-02', 1, 'zayn', 'Two access points, same network name, only one of them is supposed to exist.'),
  ('mission-w9-03', 1, 'zayn', 'Not all WPA is created equal. Know which generation you''re actually looking at, and why it matters.'),
  ('mission-w9-04', 1, 'zayn', 'Not everything wireless is Wi-Fi. Sort these by what''s actually talking.'),
  ('mission-w9-05', 1, 'zayn', 'BLE devices chatter constantly. Most of it is boring. Find what isn''t.'),
  ('mission-w9-06', 1, 'zayn', 'Locate the rogue AP physically, and design controls that stop this without taking SkyPort''s maintenance network offline.'),
  ('mission-w9-06', 2, 'zayn', 'Physically pinpointed. It was tucked into a maintenance closet, right at the edge of the legitimate AP''s coverage.'),
  ('mission-w9-06', 3, 'byte', 'I pulled its firmware identifier before Zayn powered it down. It references a project name: SENTINEL. Retired, officially, years ago.'),
  ('mission-w9-06', 4, 'zayn', 'Officially retired hardware showing up in an active attack. That''s not a coincidence I''m comfortable with.'),
  ('mission-w9-06', 5, 'zayn', 'This device didn''t get here by itself. Somewhere behind it is the Linux host that actually manages these maintenance systems. Time to stop looking at signals and start looking at the machine itself.');
insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w9-01-o1', 'mission-w9-01', 1, 'Acknowledge the briefing', 'Confirm you''re ready to work in the wireless domain.'),
  ('mission-w9-02-o1', 'mission-w9-02', 1, 'Identify the impersonator', 'Find the evidence that identifies the fake access point.'),
  ('mission-w9-03-o1', 'mission-w9-03', 1, 'Pick the strongest configuration', 'Identify the configuration most resistant to offline password cracking.'),
  ('mission-w9-04-o1', 'mission-w9-04', 1, 'Sort by technology', 'Assign each device to the wireless technology its behavior implies.'),
  ('mission-w9-05-o1', 'mission-w9-05', 1, 'Spot the anomalous BLE activity', 'Identify the BLE activity worth escalating.'),
  ('mission-w9-06-o1', 'mission-w9-06', 1, 'Pinpoint the rogue AP', 'Find the evidence that pinpoints the rogue AP''s physical location.'),
  ('mission-w9-06-o2', 'mission-w9-06', 2, 'Design the fix', 'Pick the control that stops this without disabling the maintenance network.'),
  ('mission-w9-06-o3', 'mission-w9-06', 3, 'Close the investigation', 'Confirm the rogue AP''s location and the control redesign.');
insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w9-01-o1-c1', 'mission-w9-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"zayn","text":"No cable to trace this time -- just the air itself. Ready?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-w9-02-o1-c1', 'mission-w9-02-o1', 1, 'investigation', 'Which evidence identifies the impersonating access point?', '{"evidence":[{"id":"ap1","label":"BSSID AA:11:22:33:44:55, SSID \"SkyPort-Maint\"","detail":"Vendor OUI matches inventoried maintenance hardware, signal consistent with the equipment closet''s known location"},{"id":"ap2","label":"BSSID FF:99:88:77:66:55, SSID \"SkyPort-Maint\"","detail":"Same SSID, different vendor OUI entirely, much stronger signal than any inventoried AP should produce from that area"},{"id":"ap3","label":"Channel usage","detail":"ap2 broadcasts on the same channel as ap1, which legitimate APs in this deployment are configured to avoid"},{"id":"ap4","label":"Inventory record","detail":"Only one MAC address is listed in the maintenance network''s AP inventory"}],"question":"Which evidence identifies the impersonating access point?"}'::jsonb, '{"requiredEvidenceIds":["ap2","ap3"]}'::jsonb),
  ('mission-w9-03-o1-c1', 'mission-w9-03-o1', 1, 'multiple_choice', 'Which of these wireless security configurations offers the strongest protection against offline password-cracking attempts?', '{"question":"Which of these wireless security configurations offers the strongest protection against offline password-cracking attempts?","options":[{"id":"a","text":"WEP with a 128-bit key"},{"id":"b","text":"WPA2-Personal with a short, common dictionary-word passphrase"},{"id":"c","text":"WPA3-Personal, which uses a more resistant key-exchange method (SAE) even with a weaker passphrase"},{"id":"d","text":"An open network with a captive portal login page"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-w9-04-o1-c1', 'mission-w9-04-o1', 1, 'drag_and_drop', 'Sort each device by the wireless technology it''s actually using.', '{"items":[{"id":"d1","text":"Badge reader that reads a card from a few centimeters away, no battery in the card"},{"id":"d2","text":"Wireless heart-rate monitor pairing with a nurse station tablet over a short-range low-power link"},{"id":"d3","text":"Laptop connecting to \"SkyPort-Maint\" from thirty meters away"},{"id":"d4","text":"Maintenance sensor broadcasting readings a few meters to a nearby hub, very low power"}],"targets":[{"id":"wifi","label":"Wi-Fi"},{"id":"ble","label":"Bluetooth/BLE"},{"id":"rfid","label":"RFID/NFC"}]}'::jsonb, '{"correctMapping":{"d1":"rfid","d2":"ble","d3":"wifi","d4":"ble"}}'::jsonb),
  ('mission-w9-05-o1-c1', 'mission-w9-05-o1', 1, 'investigation', 'Which BLE activity is worth escalating?', '{"evidence":[{"id":"ble1","label":"Heart-rate monitor advertisement","detail":"Standard, expected advertisement interval, matches the device''s documented behavior"},{"id":"ble2","label":"Unknown device repeatedly requesting pairing with staff phones","detail":"No corresponding inventoried device, appears only near the maintenance closet"},{"id":"ble3","label":"Wireless keyboard advertisement","detail":"Standard, expected, paired with a known workstation"},{"id":"ble4","label":"Fitness tracker advertisement from a visitor''s phone","detail":"Ordinary consumer device, no interaction attempted"}],"question":"Which BLE activity is worth escalating?"}'::jsonb, '{"requiredEvidenceIds":["ble2"]}'::jsonb),
  ('mission-w9-06-o1-c1', 'mission-w9-06-o1', 1, 'investigation', 'Which evidence pinpoints the rogue AP''s physical location?', '{"evidence":[{"id":"loc1","label":"Signal strength readings from four hallway sensors","detail":"All four readings triangulate to the maintenance closet on the third floor"},{"id":"loc2","label":"Physical access log for the maintenance closet","detail":"No badge entries during the AP''s active period -- it was already inside before monitoring began"},{"id":"loc3","label":"Signal strength readings near the nurses'' station","detail":"Consistently weak, consistent with distance from the true source"},{"id":"loc4","label":"Legitimate AP''s documented installation location","detail":"A different closet entirely, two floors away"}],"question":"Which evidence pinpoints the rogue AP''s physical location?"}'::jsonb, '{"requiredEvidenceIds":["loc1"]}'::jsonb),
  ('mission-w9-06-o2-c1', 'mission-w9-06-o2', 1, 'multiple_choice', 'What control best addresses this specific rogue-AP problem without taking the maintenance network offline?', '{"question":"What control best addresses this specific rogue-AP problem without taking the maintenance network offline?","options":[{"id":"a","text":"Disable all wireless maintenance access permanently"},{"id":"b","text":"Deploy wireless intrusion detection to alert on unrecognized BSSIDs broadcasting known SSIDs, plus physically remove the rogue hardware"},{"id":"c","text":"Change the SSID name and hope the rogue AP stops working"},{"id":"d","text":"Do nothing until the next scheduled audit"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w9-06-o3-c1', 'mission-w9-06-o3', 1, 'boss_encounter', 'Confirm the rogue AP''s location and the control redesign.', '{"stages":[{"objectiveRef":"mission-w9-06-o1","label":"The physical location"},{"objectiveRef":"mission-w9-06-o2","label":"The redesigned control"}],"task":"Confirm the rogue AP''s location and the control redesign."}'::jsonb, '{"requiredObjectiveIds":["mission-w9-06-o1","mission-w9-06-o2"],"allCorrect":true}'::jsonb);
insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w9-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),
  ('mission-w9-02-o1-c1', 'orientation', 'Same SSID doesn''t mean same device -- look past the network name.', 15, 1),
  ('mission-w9-02-o1-c1', 'concept', 'Vendor OUI and expected signal strength both say something about a device''s real identity and location.', 25, 2),
  ('mission-w9-02-o1-c1', 'tool_direction', 'Check the channel-avoidance rule this deployment is supposed to follow.', 35, 3),
  ('mission-w9-02-o1-c1', 'solution', 'ap2''s mismatched vendor OUI and unusually strong signal (contradicting inventory), combined with its channel-avoidance violation (ap3), together identify it as the impersonator -- ap1 matches inventory and ap4 confirms only one AP should exist at all.', 45, 4),
  ('mission-w9-03-o1-c1', 'orientation', 'Rule out the options that are either unencrypted or use a decades-old, broken cipher.', 10, 1),
  ('mission-w9-03-o1-c1', 'concept', 'The key-exchange method matters as much as the passphrase itself -- some methods resist offline attacks even against weak passphrases.', 20, 2),
  ('mission-w9-03-o1-c1', 'solution', 'WPA3-Personal''s SAE key exchange resists offline dictionary attacks even against a weaker passphrase, unlike WEP (broken) or WPA2 with a weak passphrase (crackable offline).', 30, 3),
  ('mission-w9-04-o1-c1', 'orientation', 'Range and power draw are strong clues -- an unpowered card and a thirty-meter connection are not the same technology.', 10, 1),
  ('mission-w9-04-o1-c1', 'concept', 'RFID/NFC works at a few centimeters with no battery required in the tag; BLE covers a short room-scale range on very low power.', 20, 2),
  ('mission-w9-04-o1-c1', 'solution', 'The unpowered badge (d1) is RFID/NFC, the short-range low-power pairings (d2, d4) are BLE, and the thirty-meter network connection (d3) is Wi-Fi.', 30, 3),
  ('mission-w9-05-o1-c1', 'orientation', 'Three of these four are completely ordinary consumer or workplace BLE traffic.', 10, 1),
  ('mission-w9-05-o1-c1', 'concept', 'A device with no inventory record actively trying to pair with staff phones is behaving very differently from a device just broadcasting its presence.', 20, 2),
  ('mission-w9-05-o1-c1', 'solution', 'The unknown device repeatedly attempting to pair with staff phones near the maintenance closet, with no inventory record, is the one that needs escalation -- the rest are ordinary, expected BLE chatter.', 30, 3),
  ('mission-w9-06-o1-c1', 'orientation', 'One of these four items is direct triangulation evidence; the rest are supporting context or unrelated.', 15, 1),
  ('mission-w9-06-o1-c1', 'concept', 'Multiple independent sensor readings converging on one location is the strongest form of physical evidence here.', 25, 2),
  ('mission-w9-06-o1-c1', 'tool_direction', 'Compare where the readings actually converge against the legitimate AP''s known location.', 35, 3),
  ('mission-w9-06-o1-c1', 'solution', 'loc1''s triangulated signal readings from four independent sensors converge on the third-floor maintenance closet -- that''s the direct physical location evidence; the others are supporting or unrelated context.', 45, 4),
  ('mission-w9-06-o2-c1', 'orientation', 'The fix needs to both stop this specific device and prevent recurrence, without disabling legitimate operations.', 15, 1),
  ('mission-w9-06-o2-c1', 'solution', 'Wireless intrusion detection plus physical removal directly addresses both the current incident and future recurrence, without disabling the maintenance network.', 25, 2),
  ('mission-w9-06-o3-c1', 'orientation', 'You''ve already gathered everything you need -- combine the location with the fix.', 20, 1),
  ('mission-w9-06-o3-c1', 'concept', 'The report needs both where the device was and what stops this from happening again.', 30, 2),
  ('mission-w9-06-o3-c1', 'tool_direction', 'State the physical location first, then the control being deployed.', 40, 3),
  ('mission-w9-06-o3-c1', 'near_solution', 'Third-floor maintenance closet; wireless intrusion detection plus physical removal.', 50, 4),
  ('mission-w9-06-o3-c1', 'solution', 'The rogue AP was physically located in the third-floor maintenance closet via signal triangulation; the fix is wireless intrusion detection for unrecognized BSSIDs plus physical removal, keeping the maintenance network operational.', 60, 5);
